<?php
namespace App\Core;
final class Accessibility
{
    public const FEATURES=['text'=>'Tamaño de lectura','spacing'=>'Espaciado y altura de línea','contrast'=>'Contraste reforzado','links'=>'Enlaces subrayados','motion'=>'Reducir movimiento','font'=>'Fuente de lectura clara','speech'=>'Lectura de selección con voz local'];
    public static function config(): array { $defaults=['enabled'=>true,'position'=>'right','features'=>array_keys(self::FEATURES)]; if (!Installer::installed()) return $defaults; $data=json_decode(Settings::get('accessibility_config','{}'),true); if (!is_array($data)) return $defaults; return ['enabled'=>($data['enabled']??true)===true,'position'=>($data['position']??'right')==='left'?'left':'right','features'=>array_values(array_intersect(array_keys(self::FEATURES),is_array($data['features']??null)?$data['features']:array_keys(self::FEATURES)))]; }
    public static function html(): string { $config=self::config(); if (!$config['enabled']) return ''; $e=ConsoleView::escape(...); $path=AdminPath::normalize(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)); $admin=$path==='/admin'||str_starts_with($path,'/admin/'); $t=static fn($v)=>Locale::text($v,$admin); $labels=['title'=>$t('Accesibilidad'),'close'=>$t('Cerrar'),'reset'=>$t('Restablecer preferencias')]; return '<link rel="stylesheet" href="/assets/accessibility.css?v=20261105"><a href="#nx-main-content" class="nx-skip-link">'.$t('Saltar al contenido').'</a><button type="button" id="nx-a11y-open" class="nx-a11y-trigger" data-position="'.$config['position'].'" aria-haspopup="dialog" aria-controls="nx-a11y-dialog" aria-label="'.$e($labels['title']).'">'.GoldensiteIcon::svg('users',24).'<span>'.$e($labels['title']).'</span></button><dialog id="nx-a11y-dialog" class="nx-a11y-dialog" aria-labelledby="nx-a11y-title"><div class="nx-a11y-heading"><h2 id="nx-a11y-title">'.$e($labels['title']).'</h2><button type="button" data-a11y-close aria-label="'.$e($labels['close']).'">×</button></div><p>'.$e($t('Preferencias de lectura guardadas solo en este navegador.')).'</p><div id="nx-a11y-controls"></div><p role="status" id="nx-a11y-status" aria-live="polite"></p><button type="button" data-a11y-reset>'.$e($labels['reset']).'</button></dialog><script id="nx-a11y-config" type="application/json">'.json_encode($config+['labels'=>array_map($t,self::FEATURES)+['noVoice'=>$t('No hay una voz local disponible en este navegador.'),'selectFirst'=>$t('Selecciona primero el texto que deseas escuchar.'),'reading'=>$t('Leyendo la selección con una voz local.'),'resetDone'=>$t('Preferencias restablecidas.')]],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script><script src="/assets/accessibility.js?v=20261105" defer></script>'; }
}
